/**
 * Client-side verdictToken verification.
 *
 * A verdictToken is an ES256 JWT decision receipt minted by the edge and bound
 * to session (`sub`), origin (`aud`), and `jti` with a short `exp`. This module
 * validates shape, signature (against the JWKS served from
 * GET /.well-known/jwks.json), expiry, session binding, and, when an expected
 * audience is supplied, origin binding. Rejection reasons are surfaced as
 * `VerdictTokenError.code`.
 */

import { ChitmarkError } from "./errors.js";
import type { ActorType, Decision } from "./types.js";

export interface VerdictTokenClaims {
  eventId: string;
  decision: Decision;
  actorType: ActorType;
  confidence: number;
  aud: string;
  sub: string;
  jti: string;
  iat: number;
  exp: number;
  degraded: boolean;
}

export type VerdictTokenErrorCode =
  | "malformed_token"
  | "wrong_algorithm"
  | "jwks_unavailable"
  | "unknown_kid"
  | "invalid_signature"
  | "expired"
  | "not_yet_valid"
  | "wrong_session"
  | "wrong_aud";

export class VerdictTokenError extends ChitmarkError {
  override name = "VerdictTokenError";

  constructor(code: VerdictTokenErrorCode, message: string) {
    super(message, { code });
  }
}

export interface VerifyVerdictTokenOptions {
  /** Expected session: token `sub` must equal this or verification fails. */
  session?: string;
  /** Expected origin: token `aud` must equal this or verification fails. */
  aud?: string;
  /** JWKS URL; defaults to https://api.chitmark.com/.well-known/jwks.json. */
  jwksUrl?: string;
  /** Pre-fetched JWKS; skips the network fetch when provided. */
  jwks?: { keys: Array<Record<string, unknown>> };
  /** Injectable fetch (Node 24+/browsers have a global). */
  fetch?: typeof fetch;
  /** Clock override for tests. */
  nowMs?: number;
  /** Clock skew tolerance in seconds; defaults to 30. */
  leewaySeconds?: number;
}

const DEFAULT_JWKS_URL = "https://api.chitmark.com/.well-known/jwks.json";
const DEFAULT_LEEWAY_SECONDS = 30;

export async function verifyVerdictToken(
  token: string,
  options: VerifyVerdictTokenOptions = {},
): Promise<VerdictTokenClaims> {
  const nowMs = options.nowMs ?? Date.now();
  const leewaySeconds = options.leewaySeconds ?? DEFAULT_LEEWAY_SECONDS;

  const parts = token.split(".");
  if (parts.length !== 3) {
    throw new VerdictTokenError("malformed_token", "verdictToken must be a JWT");
  }
  const [headerB64, payloadB64, signatureB64] = parts as [string, string, string];

  let header: Record<string, unknown>;
  let payload: Record<string, unknown>;
  try {
    header = JSON.parse(decodeBase64Url(headerB64)) as Record<string, unknown>;
    payload = JSON.parse(decodeBase64Url(payloadB64)) as Record<string, unknown>;
  } catch {
    throw new VerdictTokenError("malformed_token", "verdictToken is not valid JWT JSON");
  }

  if (header["alg"] !== "ES256") {
    throw new VerdictTokenError(
      "wrong_algorithm",
      `verdictToken must use ES256, got ${String(header["alg"])}`,
    );
  }
  const kid = typeof header["kid"] === "string" ? header["kid"] : "";
  if (!kid) {
    throw new VerdictTokenError("unknown_kid", "verdictToken is missing kid");
  }

  const exp = typeof payload["exp"] === "number" ? payload["exp"] : NaN;
  const iat = typeof payload["iat"] === "number" ? payload["iat"] : NaN;
  const nowSeconds = Math.floor(nowMs / 1000);
  if (Number.isFinite(exp) && exp < nowSeconds - leewaySeconds) {
    throw new VerdictTokenError("expired", "verdictToken has expired");
  }
  if (Number.isFinite(iat) && iat > nowSeconds + leewaySeconds) {
    throw new VerdictTokenError("not_yet_valid", "verdictToken iat is in the future");
  }

  const expectedSession = options.session;
  if (expectedSession !== undefined && payload["sub"] !== expectedSession) {
    throw new VerdictTokenError(
      "wrong_session",
      "verdictToken was minted for a different session",
    );
  }
  const expectedAud = options.aud;
  if (expectedAud !== undefined && payload["aud"] !== expectedAud) {
    throw new VerdictTokenError(
      "wrong_aud",
      "verdictToken was minted for a different origin",
    );
  }

  const jwk = await findJwk(kid, options);
  if (!jwk) {
    throw new VerdictTokenError("unknown_kid", `JWKS has no key for kid ${kid}`);
  }

  let publicKey: CryptoKey;
  try {
    publicKey = await crypto.subtle.importKey(
      "jwk",
      jwk as unknown as JsonWebKey,
      { name: "ECDSA", namedCurve: "P-256" },
      false,
      ["verify"],
    );
  } catch {
    throw new VerdictTokenError(
      "invalid_signature",
      "JWKS key is not a valid P-256 public key",
    );
  }

  const signatureBytes = decodeBase64UrlBytes(signatureB64);
  const signatureBuffer = new ArrayBuffer(signatureBytes.byteLength);
  new Uint8Array(signatureBuffer).set(signatureBytes);

  const valid = await crypto.subtle.verify(
    { name: "ECDSA", hash: "SHA-256" },
    publicKey,
    signatureBuffer,
    new TextEncoder().encode(`${headerB64}.${payloadB64}`),
  );
  if (!valid) {
    throw new VerdictTokenError(
      "invalid_signature",
      "verdictToken signature failed verification",
    );
  }

  return payload as unknown as VerdictTokenClaims;
}

async function findJwk(
  kid: string,
  options: VerifyVerdictTokenOptions,
): Promise<Record<string, unknown> | undefined> {
  let jwks = options.jwks;
  if (!jwks) {
    const jwksUrl = options.jwksUrl ?? DEFAULT_JWKS_URL;
    try {
      const fetchImpl = options.fetch ?? globalThis.fetch.bind(globalThis);
      const res = await fetchImpl(jwksUrl);
      if (!res.ok) {
        throw new Error(`JWKS fetch failed with ${res.status}`);
      }
      jwks = (await res.json()) as { keys: Array<Record<string, unknown>> };
    } catch (err) {
      throw new VerdictTokenError(
        "jwks_unavailable",
        `Failed to load JWKS from ${jwksUrl}: ${
          err instanceof Error ? err.message : "unknown error"
        }`,
      );
    }
  }
  if (!Array.isArray(jwks.keys)) {
    throw new VerdictTokenError("jwks_unavailable", "JWKS response has no keys array");
  }
  return jwks.keys.find((key) => key["kid"] === kid);
}

function decodeBase64Url(value: string): string {
  const normalized = value.replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized + "=".repeat((4 - (normalized.length % 4)) % 4);
  const binary = atob(padded);
  return new TextDecoder().decode(Uint8Array.from(binary, (ch) => ch.charCodeAt(0)));
}

function decodeBase64UrlBytes(value: string): Uint8Array {
  const normalized = value.replace(/-/g, "+").replace(/_/g, "/");
  const padded = normalized + "=".repeat((4 - (normalized.length % 4)) % 4);
  const binary = atob(padded);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
  return out;
}
