import type { PiiMode, Subject } from "../types.js";
import { hashEmailSha256, minimizeFormData, truncateIp } from "../pii.js";

/**
 * Apply client-side PII mode to a subject before the wire.
 */
export async function prepareSubject(
  subject: Subject,
  piiMode: PiiMode,
): Promise<Subject> {
  if (piiMode === "raw") {
    return subject;
  }

  if (piiMode === "none") {
    return {
      userAgent: subject.userAgent,
      headers: pickWebBotAuthHeaders(subject.headers),
    };
  }

  // hashed (default)
  const prepared: Subject = {
    userAgent: subject.userAgent,
    headers: subject.headers,
  };

  if (subject.emailSha256) {
    prepared.emailSha256 = subject.emailSha256;
  } else if (subject.email) {
    prepared.emailSha256 = await hashEmailSha256(subject.email);
  }

  if (subject.ipTrunc) {
    prepared.ipTrunc = subject.ipTrunc;
  } else if (subject.ip) {
    prepared.ipTrunc = truncateIp(subject.ip);
  }

  const hashedForm = subject.formDataHashed ?? minimizeFormData(subject.formData);
  if (hashedForm) {
    prepared.formDataHashed = hashedForm;
  }

  return prepared;
}

function pickWebBotAuthHeaders(
  headers?: Record<string, string | string[] | undefined>,
): Record<string, string> | undefined {
  if (!headers) return undefined;
  const keys = ["signature-agent", "signature-input", "signature"];
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(headers)) {
    const lower = k.toLowerCase();
    if (keys.includes(lower) && typeof v === "string") {
      out[lower] = v;
    } else if (keys.includes(lower) && Array.isArray(v) && v[0]) {
      out[lower] = v[0];
    }
  }
  return Object.keys(out).length > 0 ? out : undefined;
}

/**
 * Normalize header maps (Node / Fetch) to plain string records for JSON.
 */
export function flattenHeaders(
  headers?: Record<string, string | string[] | undefined> | Headers,
): Record<string, string> | undefined {
  if (!headers) return undefined;
  if (headers instanceof Headers) {
    const out: Record<string, string> = {};
    headers.forEach((value, key) => {
      out[key.toLowerCase()] = value;
    });
    return out;
  }
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(headers)) {
    if (typeof v === "string") out[k.toLowerCase()] = v;
    else if (Array.isArray(v) && v[0]) out[k.toLowerCase()] = v[0];
  }
  return out;
}
