import {
  ChitmarkApiError,
  ChitmarkError,
  degradedChallengeVerdict,
  enforceDegradedNeverAllow,
} from "./errors.js";
import {
  DEFAULT_TIMEOUT_MS,
  SDK_VERSION,
  envBaseUrl,
  resolveBaseUrl,
} from "./internal/constants.js";
import { flattenHeaders, prepareSubject } from "./internal/prepare.js";
import {
  verifyVerdictToken,
  type VerdictTokenClaims,
  type VerifyVerdictTokenOptions,
} from "./verify-token.js";
import type {
  ChallengeRequest,
  ChallengeResponse,
  ChallengeCompletionResponse,
  ChallengeProof,
  ChitmarkOptions,
  FeedbackRequest,
  FeedbackResponse,
  OnDegraded,
  PiiMode,
  Verdict,
  VerifyRequest,
} from "./types.js";

/**
 * Official Chitmark client (Open Agent Ledger): three verbs:
 * verify, feedback, challenge. Trust decisions on agent-mediated actions,
 * tuned by business outcomes.
 *
 * @example
 * ```ts
 * const chitmark = new Chitmark({ apiKey: process.env.CHITMARK_API_KEY! });
 * const verdict = await chitmark.verify({
 *   action: "signup",
 *   subject: { email, ip, userAgent },
 * });
 * ```
 */
export class Chitmark {
  private readonly apiKey: string;
  private readonly baseUrl: string;
  private readonly timeoutMs: number;
  private readonly piiMode: PiiMode;
  private readonly onDegraded: OnDegraded;
  private readonly fetchImpl: typeof fetch;
  private readonly clientName: string;

  constructor(options: ChitmarkOptions) {
    if (!options.apiKey) {
      throw new ChitmarkError("Chitmark apiKey is required");
    }
    if (options.onDegraded && options.onDegraded !== "challenge") {
      throw new ChitmarkError(
        'onDegraded must be "challenge": fail to challenge, never to allow',
      );
    }
    this.apiKey = options.apiKey;
    this.baseUrl = resolveBaseUrl(options.env, options.baseUrl ?? envBaseUrl());
    this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
    this.piiMode = options.piiMode ?? "hashed";
    this.onDegraded = "challenge";
    this.fetchImpl = options.fetch ?? globalThis.fetch.bind(globalThis);
    this.clientName = options.clientName ?? `chitmark-node/${SDK_VERSION}`;
  }

  /**
   * Score + route an inbound action (signup / trial / …).
   * Hot path at the edge; client budget defaults to 800ms.
   * On timeout/transport error, or a malformed verdict shape from the API,
   * returns a degraded challenge verdict (never allow, never crashes).
   *
   * Persist `v.eventId` on the account row: feedback joins only on that id.
   */
  async verify(request: VerifyRequest): Promise<Verdict> {
    const subject = await prepareSubject(
      {
        ...request.subject,
        headers: flattenHeaders(request.subject.headers),
      },
      this.piiMode,
    );

    const body: VerifyRequest = {
      ...request,
      subject,
    };

    try {
      const verdict = await this.request<Verdict>("/v1/verify", {
        method: "POST",
        body,
        idempotencyKey: request.idempotencyKey,
      });
      if (!isWellFormedVerdict(verdict)) {
        return degradedChallengeVerdict(
          "Degraded: verify returned a malformed verdict shape",
          request.session,
        );
      }
      return enforceDegradedNeverAllow(verdict);
    } catch (err) {
      if (err instanceof ChitmarkApiError) {
        throw err;
      }
      return degradedChallengeVerdict(
        err instanceof Error ? `Degraded: ${err.message}` : "Degraded: verify failed",
        request.session,
      );
    }
  }

  /**
   * Report a downstream outcome joined on the stored eventId from verify.
   * This is the data moat: attribution is a schema contract, not a fuzzy match.
   */
  async feedback(request: FeedbackRequest): Promise<FeedbackResponse> {
    return this.request<FeedbackResponse>("/v1/feedback", {
      method: "POST",
      body: request,
    });
  }

  /**
   * Issue an asymmetric-cost challenge after decision === challenge | degraded.
   */
  async challenge(request: ChallengeRequest): Promise<ChallengeResponse> {
    return this.request<ChallengeResponse>("/v1/challenge", {
      method: "POST",
      body: request,
    });
  }

  /**
   * Complete a challenge by submitting its solved proof. Clears only the bound
   * session, once. Re-verify with `context.challengeId` to have the next
   * verify honor the cleared session.
   */
  async completeChallenge(request: {
    eventId: string;
    challengeId: string;
    session?: string;
    proof: ChallengeProof;
  }): Promise<ChallengeCompletionResponse> {
    return this.request<ChallengeCompletionResponse>("/v1/challenge", {
      method: "POST",
      body: request,
    });
  }

  /**
   * Verify a verdictToken's signature against the API's JWKS and its session /
   * origin binding. Rejects expired tokens, unknown kids, and
   * invalid signatures with `VerdictTokenError`. Pass `session` to enforce
   * session binding (recommended) and `aud` to enforce origin binding.
   */
  async verifyVerdictToken(
    token: string,
    options: Omit<VerifyVerdictTokenOptions, "jwksUrl" | "fetch"> = {},
  ): Promise<VerdictTokenClaims> {
    return verifyVerdictToken(token, {
      ...options,
      jwksUrl: `${this.baseUrl}/.well-known/jwks.json`,
      fetch: this.fetchImpl,
    });
  }

  /**
   * Low-level HTTP helper. Prefer verify / feedback / challenge.
   */
  async request<T>(
    path: string,
    init: {
      method: string;
      body?: unknown;
      idempotencyKey?: string;
    },
  ): Promise<T> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), this.timeoutMs);

    try {
      const headers: Record<string, string> = {
        Authorization: `Bearer ${this.apiKey}`,
        "Content-Type": "application/json",
        Accept: "application/json",
        "User-Agent": this.clientName,
        "X-Chitmark-Client": this.clientName,
      };
      if (init.idempotencyKey) {
        headers["Idempotency-Key"] = init.idempotencyKey;
      }

      const res = await this.fetchImpl(`${this.baseUrl}${path}`, {
        method: init.method,
        headers,
        body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
        signal: controller.signal,
      });

      const text = await res.text();
      let parsed: unknown = undefined;
      if (text) {
        try {
          parsed = JSON.parse(text) as unknown;
        } catch {
          parsed = text;
        }
      }

      if (!res.ok) {
        const errBody =
          typeof parsed === "object" && parsed !== null
            ? (parsed as { error?: string; message?: string; code?: string })
            : text;
        const normalized =
          typeof errBody === "string"
            ? errBody
            : {
                error: errBody.error ?? `http_${res.status}`,
                message: errBody.message,
                code: errBody.code,
              };
        throw new ChitmarkApiError(res.status, normalized);
      }

      return parsed as T;
    } catch (err) {
      if (err instanceof ChitmarkApiError) throw err;
      if (err instanceof Error && err.name === "AbortError") {
        throw new ChitmarkError(`Request timed out after ${this.timeoutMs}ms`, {
          code: "timeout",
        });
      }
      throw err instanceof Error
        ? new ChitmarkError(err.message, { code: "transport" })
        : new ChitmarkError("Unknown transport error", { code: "transport" });
    } finally {
      clearTimeout(timer);
    }
  }

  /** Public accessors for inspection / tests. */
  get config(): {
    baseUrl: string;
    timeoutMs: number;
    piiMode: PiiMode;
    onDegraded: OnDegraded;
  } {
    return {
      baseUrl: this.baseUrl,
      timeoutMs: this.timeoutMs,
      piiMode: this.piiMode,
      onDegraded: this.onDegraded,
    };
  }
}

const VERDICT_DECISIONS: ReadonlySet<string> = new Set(["allow", "challenge", "deny"]);

/**
 * Minimal shape guard for a 200 verify response. A malformed verdict must
 * never be treated as allow: the gating fields are what gate correctness.
 */
export function isWellFormedVerdict(value: unknown): value is Verdict {
  if (typeof value !== "object" || value === null) return false;
  const v = value as Partial<Verdict>;
  return (
    typeof v.decision === "string" &&
    VERDICT_DECISIONS.has(v.decision) &&
    typeof v.eventId === "string" &&
    v.eventId.length > 0 &&
    typeof v.degraded === "boolean"
  );
}
