import type { Chitmark } from "../client.js";
import type { Action, Verdict } from "../types.js";

export interface NextVerifyOptions {
  action: Action;
  surface?: string;
  session?: string;
  body?: {
    email?: string;
    [key: string]: unknown;
  };
}

/**
 * Helper for Next.js App Router route handlers.
 * Returns the verdict; caller maps decision → Response.
 *
 * @example
 * ```ts
 * const v = await verifyNextRequest(chitmark, req, { action: "signup", body });
 * const status = verdictToHttpStatus(v);
 * ```
 */
export async function verifyNextRequest(
  client: Chitmark,
  req: Request,
  options: NextVerifyOptions,
): Promise<Verdict> {
  const url = new URL(req.url);
  return client.verify({
    action: options.action,
    surface: options.surface ?? `${url.host}${url.pathname}`,
    session: options.session,
    subject: {
      email: options.body?.email,
      ip: req.headers.get("x-forwarded-for") ?? "",
      userAgent: req.headers.get("user-agent") ?? "",
      headers: Object.fromEntries(req.headers),
      formData: options.body,
    },
  });
}

export { verdictToHttpStatus } from "../http-status.js";
