/**
 * Client-side PII minimization helpers.
 * Default SDK mode hashes email and truncates IP before leaving the customer process.
 */

/**
 * SHA-256 hex digest of lowercased, trimmed email.
 * Uses Web Crypto (Node 18+, browsers, Workers).
 */
export async function hashEmailSha256(email: string): Promise<string> {
  const normalized = email.trim().toLowerCase();
  const data = new TextEncoder().encode(normalized);
  const digest = await crypto.subtle.digest("SHA-256", data);
  return bufferToHex(digest);
}

/**
 * Truncate IPv4 to /24 or IPv6 to /48 for coarse geo without host identity.
 */
export function truncateIp(ip: string): string {
  const trimmed = ip.trim();
  // IPv4 (optionally from x-forwarded-for first hop)
  const first = trimmed.split(",")[0]?.trim() ?? trimmed;
  if (first.includes(".") && !first.includes(":")) {
    const parts = first.split(".");
    if (parts.length === 4) {
      return `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
    }
  }
  // IPv6: keep first 3 hextets (~/48)
  if (first.includes(":")) {
    const hextets = first.split(":").filter(Boolean);
    const head = hextets.slice(0, 3).join(":");
    return `${head}::/48`;
  }
  return first;
}

/**
 * Reduce form payload to non-PII keys (domain-style fields only for hashed mode).
 * Free-text is dropped; companyDomain-style keys are kept as-is when domain-like.
 */
export function minimizeFormData(
  formData: Record<string, unknown> | undefined,
): Record<string, unknown> | undefined {
  if (!formData) return undefined;
  const allowed = new Set([
    "companyDomain",
    "company_domain",
    "domain",
    "plan",
    "referrer",
    "utm_source",
    "utm_medium",
    "utm_campaign",
  ]);
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(formData)) {
    if (allowed.has(key) && value != null) {
      out[key] = value;
    }
  }
  return Object.keys(out).length > 0 ? out : undefined;
}

function bufferToHex(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let hex = "";
  for (const b of bytes) {
    hex += b.toString(16).padStart(2, "0");
  }
  return hex;
}
