import type { Verdict } from "./types.js";

export const CHITMARK_HTTP_STATUS = {
  ok: 200,
  created: 201,
  badRequest: 400,
  unauthorized: 401,
  forbidden: 403,
  notFound: 404,
  conflict: 409,
  preconditionRequired: 428,
  tooManyRequests: 429,
} as const;

export type ChitmarkHttpStatus =
  (typeof CHITMARK_HTTP_STATUS)[keyof typeof CHITMARK_HTTP_STATUS];

export const CHITMARK_HTTP_STATUS_MEANING = {
  ok: "Request succeeded. For verify gates, continue only after an explicit non-degraded allow.",
  created: "Resource was created after an explicit non-degraded allow.",
  badRequest: "Required request fields are missing or malformed.",
  unauthorized: "API key is missing or invalid.",
  forbidden: "Verify returned deny; block the action.",
  notFound: "Referenced Chitmark resource was not found.",
  conflict: "Idempotency key was reused with a materially different payload.",
  preconditionRequired:
    "Verify returned challenge or degraded; require friction before continuing.",
  tooManyRequests: "Request was rate limited.",
} as const satisfies Record<keyof typeof CHITMARK_HTTP_STATUS, string>;

export function verdictToHttpStatus(verdict: Verdict): ChitmarkHttpStatus {
  if (verdict.degraded || verdict.decision === "challenge") {
    return CHITMARK_HTTP_STATUS.preconditionRequired;
  }
  if (verdict.decision === "deny") return CHITMARK_HTTP_STATUS.forbidden;
  return CHITMARK_HTTP_STATUS.ok;
}
