import type { ChitmarkErrorBody, Decision, Verdict } from "./types.js";

/**
 * Base error for all Chitmark client failures.
 */
export class ChitmarkError extends Error {
  override name = "ChitmarkError";
  readonly status?: number;
  readonly code?: string;
  readonly body?: ChitmarkErrorBody | string;

  constructor(
    message: string,
    options?: { status?: number; code?: string; body?: ChitmarkErrorBody | string },
  ) {
    super(message);
    this.status = options?.status;
    this.code = options?.code;
    this.body = options?.body;
  }
}

/**
 * Raised when the API returns a non-2xx response.
 */
export class ChitmarkApiError extends ChitmarkError {
  override name = "ChitmarkApiError";

  constructor(status: number, body: ChitmarkErrorBody | string, message?: string) {
    const msg =
      message ??
      (typeof body === "string"
        ? body
        : body.message || body.error || `Chitmark API error (${status})`);
    super(msg, {
      status,
      code: typeof body === "object" ? (body.code ?? body.error) : undefined,
      body,
    });
  }
}

/**
 * Build the degraded challenge verdict used on timeout / transport failure.
 * Golden rule: fail to challenge, never to allow.
 */
export function degradedChallengeVerdict(reason: string, session?: string): Verdict {
  return {
    decision: "challenge" satisfies Decision,
    actorType: "unknown",
    confidence: 0,
    reasons: [reason],
    principal: {
      resolved: false,
      identityBasis: ["degraded"],
    },
    verdictToken: "",
    eventId: `evt_degraded_${session ?? "unknown"}`,
    degraded: true,
    enforcementMode: "enforce",
  };
}

/**
 * Ensure degraded responses never surface as allow (defense in depth client-side).
 */
export function enforceDegradedNeverAllow(verdict: Verdict): Verdict {
  if (verdict.degraded && verdict.decision === "allow") {
    return {
      ...verdict,
      decision: "challenge",
      reasons: [
        ...verdict.reasons,
        "Client enforced: degraded decision must not be allow",
      ],
    };
  }
  return verdict;
}
