import type { Chitmark } from "../client.js";
import { CHITMARK_HTTP_STATUS } from "../http-status.js";
import type { Action, Verdict } from "../types.js";

/**
 * Minimal Express-compatible types (no express dependency).
 */
export interface ExpressLikeRequest {
  hostname?: string;
  path?: string;
  ip?: string;
  body?: {
    email?: string;
    [key: string]: unknown;
  };
  headers: Record<string, string | string[] | undefined>;
}

export interface ExpressLikeResponse {
  status: (code: number) => ExpressLikeResponse;
  json: (body: unknown) => unknown;
  locals: Record<string, unknown>;
}

export type ExpressNext = (err?: unknown) => void;

export interface GateOptions {
  /** Optional session binder. */
  session?: (req: ExpressLikeRequest) => string | undefined;
  /** Custom surface string. */
  surface?: (req: ExpressLikeRequest) => string;
}

/**
 * Express middleware factory: verify on the hot path, attach verdict to res.locals.
 *
 * - deny → 403
 * - challenge (incl. degraded) → 428
 * - allow → next()
 *
 * @example
 * ```ts
 * app.post("/signup", chitmarkGate(chitmark, "signup"), signupHandler);
 * ```
 */
export function chitmarkGate(
  client: Chitmark,
  action: Action,
  options: GateOptions = {},
): (
  req: ExpressLikeRequest,
  res: ExpressLikeResponse,
  next: ExpressNext,
) => Promise<void> {
  return async (req, res, next) => {
    try {
      const surface = options.surface?.(req) ?? `${req.hostname ?? ""}${req.path ?? ""}`;
      const session = options.session?.(req);

      const v: Verdict = await client.verify({
        action,
        surface,
        session,
        subject: {
          email: req.body?.email,
          ip: req.ip,
          userAgent:
            (typeof req.headers["user-agent"] === "string"
              ? req.headers["user-agent"]
              : undefined) ?? "",
          headers: req.headers,
          formData: req.body,
        },
      });

      res.locals.chitmark = v;

      if (v.degraded || v.decision === "challenge") {
        res
          .status(CHITMARK_HTTP_STATUS.preconditionRequired)
          .json({ challenge: true, eventId: v.eventId });
        return;
      }
      if (v.decision === "deny") {
        res
          .status(CHITMARK_HTTP_STATUS.forbidden)
          .json({ error: "blocked", eventId: v.eventId });
        return;
      }
      next();
    } catch (err) {
      next(err);
    }
  };
}
