import type { ChitmarkEnv } from "../types.js";

export const DEFAULT_BASE_URLS: Record<ChitmarkEnv, string> = {
  production: "https://api.chitmark.com",
  staging: "https://api.staging.chitmark.com",
  development: "http://127.0.0.1:8787",
};

export const DEFAULT_TIMEOUT_MS = 800;
/** Keep in parity with the package version and the Python SDK. */
export const SDK_VERSION = "0.5.1";

export function resolveBaseUrl(
  env: ChitmarkEnv = "production",
  baseUrl?: string,
): string {
  return (baseUrl ?? DEFAULT_BASE_URLS[env]).replace(/\/$/, "");
}

/**
 * CHITMARK_BASE_URL environment override, when present (Node only, no-op on
 * Workers/browsers where `process` is undefined).
 */
export function envBaseUrl(): string | undefined {
  if (typeof process === "undefined") return undefined;
  const value = process.env?.CHITMARK_BASE_URL;
  return value ? value.trim() : undefined;
}
